replacements.new:
cards.forEach(function(card){
  card.querySelectorAll('.tag,h3,p,button').forEach(function(slot){slot.style.minHeight='';});
});
if(getComputedStyle(grid).gridTemplateColumns.trim().split(/\s+/).length===1) return;
var rows=new Map();
cards.forEach(function(card){
  var top=card.offsetTop;
  if(!rows.has(top)) rows.set(top,[]);
  rows.get(top).push(card);
});
rows.forEach(function(row){
  ['.tag','h3'].forEach(function(selector){
    var slots=row.map(function(card){return card.querySelector(selector);}).filter(Boolean);
    var height=Math.ceil(Math.max(0,...slots.map(function(slot){return slot.getBoundingClientRect().height;})));
    slots.forEach(function(slot){slot.style.minHeight=height+'px';});
  });
});
